@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* ──────────────────────────────────────────────────────────
     BRAND SWATCHES (single source of raw hex — Vega owns these)
  ────────────────────────────────────────────────────────── */
  --color-ink-black: #0a0a0f;
  --color-electric-purple: #7c3aed;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC PALETTE — LIGHT MODE
  ────────────────────────────────────────────────────────── */

  /* Page canvas — warm off-white so cards "float" on it */
  --color-background: oklch(97.5% 0.003 264);

  /* Text — near-black with a cool blue tint */
  --color-foreground: oklch(13% 0.015 264);

  /* Card surface — pure white, visible against the page bg */
  --color-card: oklch(100% 0 0);
  --color-card-foreground: oklch(13% 0.015 264);

  --color-popover: oklch(100% 0 0);
  --color-popover-foreground: oklch(13% 0.015 264);

  /* Primary — same purple, unchanged */
  --color-primary: oklch(52% 0.24 292);
  --color-primary-foreground: oklch(99% 0 0);

  /* Secondary — subtle lavender tint */
  --color-secondary: oklch(95.5% 0.012 292);
  --color-secondary-foreground: oklch(28% 0.06 292);

  /* Muted — for backgrounds of non-interactive elements */
  --color-muted: oklch(95% 0.006 264);
  --color-muted-foreground: oklch(52% 0.02 264);

  /* Accent — light purple for hover states and chips */
  --color-accent: oklch(95% 0.018 292);
  --color-accent-foreground: oklch(35% 0.14 292);

  /* Destructive — unchanged */
  --color-destructive: oklch(59% 0.22 27);
  --color-destructive-foreground: oklch(99% 0 0);

  /* Borders — visible but light */
  --color-border: oklch(91% 0.008 264);
  --color-input: oklch(91% 0.008 264);
  --color-ring: oklch(52% 0.24 292);

  /* ──────────────────────────────────────────────────────────
     SHADOWS — custom (never use Tailwind default shadow-sm/md)
  ────────────────────────────────────────────────────────── */

  /* Soft border shadow for cards on white */
  --shadow-soft: 0 1px 2px 0 oklch(13% 0.015 264 / 0.05), 0 1px 3px 0 oklch(13% 0.015 264 / 0.04);

  /* Standard card elevation — visible on off-white page */
  --shadow-card: 0 1px 3px 0 oklch(13% 0.015 264 / 0.07), 0 1px 2px -1px oklch(13% 0.015 264 / 0.05);

  /* Hover elevation */
  --shadow-card-hover: 0 4px 12px -2px oklch(13% 0.015 264 / 0.10), 0 2px 6px -2px oklch(13% 0.015 264 / 0.07);

  /* Medium depth for drawers, modals */
  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 264 / 0.10), 0 2px 8px -2px oklch(13% 0.015 264 / 0.07);

  /* ──────────────────────────────────────────────────────────
     RADIUS
  ────────────────────────────────────────────────────────── */
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  /* ──────────────────────────────────────────────────────────
     TYPOGRAPHY
  ────────────────────────────────────────────────────────── */
  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;

  /* ──────────────────────────────────────────────────────────
     SIDEBAR TOKENS (shadcn sidebar primitives)
  ────────────────────────────────────────────────────────── */
  --sidebar: oklch(100% 0 0);
  --sidebar-background: oklch(100% 0 0);
  --sidebar-foreground: oklch(22% 0.015 264);
  --sidebar-primary: oklch(52% 0.24 292);
  --sidebar-primary-foreground: oklch(99% 0 0);
  --sidebar-accent: oklch(95.5% 0.018 292);
  --sidebar-accent-foreground: oklch(35% 0.14 292);
  --sidebar-border: oklch(91% 0.008 264);
  --sidebar-ring: oklch(52% 0.24 292);
  --sidebar-width: 15rem;
  --sidebar-width-mobile: 18rem;
  --sidebar-width-icon: 3.5rem;

  /* shadcn token aliases */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* ──────────────────────────────────────────────────────────
     PAGE LAYOUT — light mode
  ────────────────────────────────────────────────────────── */
  --color-page-bg: oklch(97.5% 0.003 264);
  --color-header-bg: oklch(100% 0 0);
  --color-surface-1: oklch(100% 0 0);
  --color-surface-2: oklch(97.5% 0.003 264);

  /* ──────────────────────────────────────────────────────────
     STATUS BADGES — tattoo booking lifecycle
  ────────────────────────────────────────────────────────── */
  --color-status-pending: oklch(70% 0.16 72);
  --color-status-confirmed: oklch(62% 0.24 292);
  --color-status-in-progress: oklch(60% 0.2 200);
  --color-status-completed: oklch(58% 0.18 145);
  --color-status-cancelled: oklch(55% 0.02 264);
  --color-status-no-show: oklch(55% 0.22 27);

  /* ──────────────────────────────────────────────────────────
     NEON ACCENT
  ────────────────────────────────────────────────────────── */
  --color-neon-purple: oklch(72% 0.28 292);
  --color-neon-purple-glow: 0 0 20px oklch(72% 0.28 292 / 0.4);

  /* ──────────────────────────────────────────────────────────
     CONSENT — submission status colors (Sprint 5)
  ────────────────────────────────────────────────────────── */
  --color-consent-signed:       oklch(58% 0.18 145);
  --color-consent-pending:      oklch(70% 0.16 72);
  --color-consent-expired:      oklch(55% 0.02 264);
  --color-consent-deleted:      oklch(45% 0.02 264);
  --color-consent-opened:       oklch(60% 0.22 230);

  /* ──────────────────────────────────────────────────────────
     CONSENT — template kind badge colors
  ────────────────────────────────────────────────────────── */
  --color-kind-tattoo:   oklch(62% 0.24 292);
  --color-kind-piercing: oklch(60% 0.22 230);
  --color-kind-pmu:      oklch(60% 0.24 340);
  --color-kind-touchup:  oklch(70% 0.16 72);
  --color-kind-minor:    oklch(55% 0.22 27);

  /* ──────────────────────────────────────────────────────────
     CONSENT — signature pad
  ────────────────────────────────────────────────────────── */
  --color-sig-bg:              oklch(6% 0.01 264);
  --color-sig-stroke:          oklch(97% 0.01 264);
  --color-sig-border:          oklch(28% 0.04 292);
  --color-sig-border-active:   oklch(62% 0.24 292 / 0.6);

  /* ──────────────────────────────────────────────────────────
     CONSENT — public signing page
  ────────────────────────────────────────────────────────── */
  --color-signing-bg:              oklch(8% 0.01 264);
  --color-signing-card:            oklch(12% 0.02 264);
  --color-signing-progress-track:  oklch(20% 0.02 264);
  --color-signing-progress-fill:   var(--studio-brand-color, oklch(62% 0.24 292));

  /* ──────────────────────────────────────────────────────────
     CONSENT — template builder
  ────────────────────────────────────────────────────────── */
  --color-builder-panel-bg:       oklch(10% 0.015 264);
  --color-builder-section-bg:     oklch(14% 0.02 264);
  --color-builder-section-hover:  oklch(17% 0.025 264);
  --color-builder-section-drag:   oklch(12% 0.015 264 / 0.8);
  --color-builder-palette-item:   oklch(16% 0.02 264);

  /* ──────────────────────────────────────────────────────────
     CONSENT — REACH disclosure
  ────────────────────────────────────────────────────────── */
  --color-reach-bg:     oklch(12% 0.03 292 / 0.4);
  --color-reach-border: oklch(62% 0.24 292 / 0.2);

  /* ──────────────────────────────────────────────────────────
     RETENTION COUNTDOWN
  ────────────────────────────────────────────────────────── */
  --color-retention-safe: oklch(55% 0.02 264);
  --color-retention-warn: oklch(70% 0.16 72);
  --color-retention-crit: oklch(55% 0.22 27);

  /* ──────────────────────────────────────────────────────────
     ANIMATIONS
  ────────────────────────────────────────────────────────── */
  --animate-fade-in-up: fade-in-up 0.35s ease-out;
  --animate-fade-in: fade-in 0.2s ease-out;
  --animate-slide-in-right: slide-in-right 0.25s ease-out;

