.chip-role-artist       { background: oklch(60% 0.24 340 / 0.12); color: oklch(68% 0.18 340); border: 1px solid oklch(60% 0.24 340 / 0.3); }
.chip-role-receptionist { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.chip-role-guest-artist { background: oklch(55% 0.18 145 / 0.12); color: oklch(62% 0.14 145); border: 1px solid oklch(55% 0.18 145 / 0.3); }

/* ── Invite status badges (Sprint 6) ── */
.badge-invite-pending  { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.badge-invite-expired  { background: oklch(55% 0.02 264 / 0.12); color: oklch(60% 0.02 264); border: 1px solid oklch(55% 0.02 264 / 0.3); }
.badge-invite-revoked  { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }
.badge-invite-accepted { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }

/* ── Schedule grid slot (Sprint 6) ── */
.schedule-slot {
  background: var(--color-schedule-slot-bg);
  border: 1px solid var(--color-schedule-slot-border);
  border-radius: var(--radius-sm);
  color: var(--color-schedule-slot-text);
  font-size: 0.6875rem;
  font-weight: 500;
  transition: background 100ms ease-out, border-color 100ms ease-out;
  cursor: pointer;
  user-select: none;
}
.schedule-slot:hover {
  background: oklch(62% 0.24 292 / 0.25);
  border-color: oklch(62% 0.24 292 / 0.7);
}
.schedule-slot[data-dragging="true"] {
  opacity: 0.7;
  background: var(--color-schedule-slot-drag);
}

/* ── Schedule time-off overlay on grid (Sprint 6) ── */
.schedule-time-off {
  background: var(--color-schedule-time-off-bg);
  border: 1px solid var(--color-schedule-time-off-border);
  border-radius: var(--radius-sm);
}
.schedule-blocked {
  background: var(--color-schedule-blocked-bg);
  border: 1px solid var(--color-schedule-blocked-border);
  border-radius: var(--radius-sm);
}

/* ── Permissions matrix (Sprint 6) ── */
.perm-check { color: var(--color-perm-check); }
.perm-cross { color: var(--color-perm-cross); }
.perm-group-row { background: var(--color-perm-group-header); }

/* ── Calendar color swatch dot (Sprint 6) ── */
.cal-color-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── Invite accept page (Sprint 6) ── */
.invite-accept-page {
  background: oklch(6% 0.01 264);
  min-height: 100dvh;
}
.invite-accept-card {
  background: oklch(10% 0.015 264);
  border: 1px solid oklch(22% 0.025 264);
}

/* ── Deactivated member row ── */
.badge-deactivated { background: oklch(45% 0.02 264 / 0.12); color: oklch(55% 0.02 264); border: 1px solid oklch(45% 0.02 264 / 0.3); }

/* ── Commission record status badges (Sprint 7) ── */
.badge-commission-pending   { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.badge-commission-approved  { background: oklch(62% 0.24 292 / 0.12); color: oklch(72% 0.18 292); border: 1px solid oklch(62% 0.24 292 / 0.3); }
.badge-commission-paid      { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-commission-cancelled { background: oklch(55% 0.02 264 / 0.12); color: oklch(65% 0.02 264); border: 1px solid oklch(55% 0.02 264 / 0.3); }
.badge-commission-disputed  { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }

/* ── Adjustment kind badges (Sprint 7) ── */
.badge-adj-bonus       { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-adj-penalty     { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }
.badge-adj-correction  { background: oklch(60% 0.22 230 / 0.12); color: oklch(68% 0.18 230); border: 1px solid oklch(60% 0.22 230 / 0.3); }
.badge-adj-guest-split { background: oklch(62% 0.24 292 / 0.12); color: oklch(72% 0.18 292); border: 1px solid oklch(62% 0.24 292 / 0.3); }
.badge-adj-other       { background: oklch(60% 0.02 264 / 0.12); color: oklch(68% 0.02 264); border: 1px solid oklch(60% 0.02 264 / 0.3); }

/* ── Rule match type pill (Sprint 7) ── */
.pill-rule-service_specific { background: oklch(62% 0.24 292 / 0.12); color: oklch(72% 0.18 292); border: 1px solid oklch(62% 0.24 292 / 0.3); }
.pill-rule-catch_all        { background: oklch(60% 0.22 230 / 0.12); color: oklch(68% 0.18 230); border: 1px solid oklch(60% 0.22 230 / 0.3); }
.pill-rule-artist_default   { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.pill-rule-none             { background: oklch(55% 0.02 264 / 0.12); color: oklch(65% 0.02 264); border: 1px solid oklch(55% 0.02 264 / 0.3); }

/* ── Dispute status badges (Sprint 7) ── */
.badge-dispute-open      { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.badge-dispute-resolved  { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-dispute-dismissed { background: oklch(55% 0.02 264 / 0.12); color: oklch(65% 0.02 264); border: 1px solid oklch(55% 0.02 264 / 0.3); }

/* ── Commission preview card (Sprint 7) ── */
.commission-preview {
  background: oklch(12% 0.025 292 / 0.4);
  border: 1px solid oklch(62% 0.24 292 / 0.25);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
}
.commission-preview-label {
  color: oklch(50% 0.04 264);
  font-size: 0.6875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.commission-preview-value {
  color: oklch(90% 0.02 264);
  font-size: 0.875rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.commission-preview-total {
  color: oklch(72% 0.18 292);
  font-size: 1rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* ── Bulk approval sticky footer (Sprint 7) ── */
.bulk-action-footer {
  position: sticky;
  bottom: 0;
  background: oklch(10% 0.02 264 / 0.96);
  border-top: 1px solid oklch(28% 0.04 264);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 0.75rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  z-index: 20;
}

/* ── Rule timeline bar (Sprint 7) ── */
.rule-timeline-segment {
  height: 4px;
  border-radius: 2px;
  transition: opacity 150ms ease-out;
}
.rule-timeline-active  { background: oklch(62% 0.24 292 / 0.8); }
.rule-timeline-past    { background: oklch(40% 0.02 264 / 0.5); }
.rule-timeline-future  { background: oklch(60% 0.22 230 / 0.5); }

/* ── Payroll run status badges (Sprint 8) ── */
.badge-payroll-draft      { background: oklch(55% 0.02 264 / 0.12); color: oklch(65% 0.02 264); border: 1px solid oklch(55% 0.02 264 / 0.3); }
.badge-payroll-calculated { background: oklch(60% 0.22 230 / 0.12); color: oklch(68% 0.18 230); border: 1px solid oklch(60% 0.22 230 / 0.3); }
.badge-payroll-approved   { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.badge-payroll-paid       { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-payroll-cancelled  { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }

/* ── Tax form status badges (Sprint 8) ── */
.badge-tax-draft     { background: oklch(55% 0.02 264 / 0.12); color: oklch(65% 0.02 264); border: 1px solid oklch(55% 0.02 264 / 0.3); }
.badge-tax-generated { background: oklch(60% 0.22 230 / 0.12); color: oklch(68% 0.18 230); border: 1px solid oklch(60% 0.22 230 / 0.3); }
.badge-tax-sent      { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-tax-corrected { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.badge-tax-voided    { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }

/* ── W-9 status badges (Sprint 8) ── */
.badge-w9-collected { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-w9-missing   { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }
.badge-w9-expired   { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }

/* ── Artist pay status badges (Sprint 8) ── */
.badge-pay-pending  { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.badge-pay-paid     { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
